arguments.command:
curl -sS https://api.linear.app/graphql -H 'Content-Type: application/json' -d '{"query":"{ __schema { queryType { fields { name args { name type { name kind ofType { name } } } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['__schema']['queryType']['fields']:
    if f['name'] in ('documents','document','project','searchDocuments'):
        print(f['name'])
        for a in f['args']:
            t=a['type']
            print('  ',a['name'],t.get('name') or (t.get('ofType') or {}).get('name'), t.get('kind'))
"

